def retry_with_backoff(call, attempts=5):
    """Retry a failed call with exponential backoff."""
    for attempt in range(attempts):
        try:
            return call()
        except PaymentError as error:
            sleep(2 ** attempt)
    raise error

class PaymentError(Exception):
    """Raised when a payment fails: the card was declined or the gateway timed out."""
    pass

